import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
INF = float('inf')
# dp[j][i]: minimum cost of a subsequence with j elements whose last element is a[i]
dp = [[INF] * n for _ in range(k + 1)]
for i in range(n):
    dp[1][i] = 0
for j in range(2, k + 1):
    for i in range(n):
        for p in range(i):
            if dp[j - 1][p] + abs(a[i] - a[p]) < dp[j][i]:
                dp[j][i] = dp[j - 1][p] + abs(a[i] - a[p])
print(min(dp[k]))

